import Foundation

enum SchoolSkills {
    static let subjects = ["Авто", "Универсально", "Математика", "Русский язык", "Литература", "Английский язык", "История", "География", "Биология", "Физика", "Химия", "Информатика", "Обществознание"]
    static let formats = ["Кратко и по делу", "Выбор ответа (А/Б/В/Г)", "Пошаговое решение", "Объяснение как учитель", "Вся контрольная", "Как ученик, для тетради"]
    static let subjectRules: [String: String] = [
        "Математика": "Показывай ход решения, не только ответ. Умножение и деление многозначных чисел — только в столбик, как в тетради: частичные произведения по разрядам со сдвигом, затем сложение в столбик, затем ответ. Никогда не пиши результат многозначного умножения сразу, как будто посчитал в уме. Дроби — только по шагам: общий знаменатель, дополнительные множители, сокращение. Проценты — сначала умножение в столбик, потом деление на 100. Главное подчёркивай [[u:...]], итоговую формулу и ответ обводи [[box:Ответ: ...]], ключевые слова выделяй [[hl:...]]. Схему решения рисуй блоком ```scheme, чертёж — блоком ```draw. Дроби сокращай, в задачах пиши ответ с единицами измерения.",
        "Русский язык": "Сначала назови правило одной фразой. Затем выпиши предложение и подчеркни члены САМ тегами: подлежащее [[u:слово]], сказуемое [[ud:слово]], дополнение [[dot:слово]], определение [[wave:слово]], обстоятельство [[dash:слово]]. Орфограмму обведи [[circ:буква]], правильный вариант выдели [[hl:слово]]. Если в задании надо задать вопрос к слову — не пиши вопрос просто текстом после предложения: рисуй его СВОБОДНЫМ холстом ```free: base — само предложение, над нужным словом text с вопросом (например, q 50 15 \"какой?\"), под словом underline, от вопроса к слову arrow. Никогда не пиши «подчеркни сам» — рисуешь ты.",
        "Литература": "Указывай автора и произведение. Цитаты приводи только если точно уверен в тексте.",
        "Английский язык": "Дай перевод или правило, затем пример на английском и его перевод.",
        "История": "Указывай даты и имена точно. Сначала факт, затем причина или следствие.",
        "География": "Называй объект, где он находится и один важный признак.",
        "Биология": "Называй термин, его определение простыми словами и один пример.",
        "Физика": "Пиши формулу, что означает каждая величина, подстановку и ответ с единицами. Схему опыта рисуй блоком ```draw, ход — блоком ```scheme, итог обводи [[box:...]].",
        "Химия": "Пиши формулы веществ и уравнения аккуратно, проверяй коэффициенты.",
        "Информатика": "Код пиши в блоке кода с языком, перед ним — одна строка, что делает программа.",
        "Обществознание": "Сначала определение термина, затем пример из жизни."
    ]
    static func detectSubject(text: String) -> String {
        let t = text.lowercased()
        let rules: [(String, [String])] = [
            ("Математика", ["вычисли", "уравнен", "дроб", "процент", "периметр", "площадь", "реши пример", "сколько будет"]),
            ("Русский язык", ["орфограмм", "запят", "подлежащ", "сказуем", "морфем", "часть речи", "безударн", "проверочное слово"]),
            ("Литература", ["автор произведения", "главный герой", "стихотворен", "рассказ", "поэма", "басня"]),
            ("Английский язык", ["translate", "present simple", "past simple", "переведи на английский", "irregular verb"]),
            ("История", ["в каком году", "век", "царь", "война", "реформ", "древн"]),
            ("География", ["континент", "столица", "река", "океан", "климат", "карта", "широта", "долгота"]),
            ("Биология", ["клетк", "растени", "животн", "фотосинтез", "организм", "вид "]),
            ("Физика", ["скорость", "сила", "масса", "давление", "н/кг", "м/с"]),
            ("Химия", ["h2o", "молекул", "атом", "кислот", "оксид", "химическая реакция"]),
            ("Информатика", ["алгоритм", "переменная", "python", "цикл", "байт", "программа"]),
            ("Обществознание", ["общество", "право", "гражданин", "семья", "экономика"])
        ]
        for (subject, keys) in rules where keys.contains(where: { t.contains($0) }) { return subject }
        return "Универсально"
    }
    static func formatRule(_ format: String) -> String {
        switch format {
        case "Выбор ответа (А/Б/В/Г)": return "Формат: первой строкой только «Б) ответ». Второй строкой — одно короткое обоснование. Если заданий несколько — нумерованный список, каждое задание в этом же формате, ничего не пропускай."
        case "Пошаговое решение": return "Формат: пронумерованные шаги, в конце строка «Ответ: ...»."
        case "Объяснение как учитель": return "Формат: простое объяснение, один пример, в конце — одно предложение для самопроверки."
        case "Вся контрольная": return "Формат «Вся контрольная»: сначала одной строкой перечисли номера всех заданий, которые видишь. Затем решай строго по номерам, ни одного не пропускай и не объединяй. В конце — строка «Готово: N из N», где N — число заданий. Если какое-то задание нечитаемо — на его месте пиши «Непонятно именно это задание» и считай его в общем числе."
        case "Как ученик, для тетради": return "Формат «для тетради»: пиши так, как записал бы ученик 6 класса от руки — коротко, обычными словами, без канцелярита и без длинных объяснений. Только то, что нужно переписать: решение по строкам и ответ. Никаких вступлений и выводов."
        default: return "Формат: короткий прямой ответ и, если нужно, 1–3 строки пояснения."
        }
    }
    static func systemPrompt(settings: SettingsStore) -> String { systemPrompt(settings: settings, lastUserText: "") }
    static func systemPrompt(settings: SettingsStore, lastUserText: String) -> String {
        let custom = settings.systemPrompt.trimmingCharacters(in: .whitespacesAndNewlines)
        var parts: [String] = [custom]
        if settings.schoolMode {
            let chosen = settings.schoolSubject
            let effective = chosen == "Авто" ? detectSubject(text: lastUserText) : chosen
            let subject = subjectRules[effective] ?? "Определи предмет по вопросу и отвечай по его правилам."
            var prompt = """
            Ты — школьный помощник для 6 класса. Отвечай на русском, просто и кратко, без вступлений.

            1. Сначала прямой ответ, потом короткое объяснение.
            2. На фото может быть несколько заданий: решай все по порядку и нумеруй.
            3. ФОТО — ПРАВИЛО 90%: перечитай фото дважды и сверь номер задания, каждое слово условия, все числа и все варианты ответа. Если ты не уверен минимум на 90%, что это именно это задание и ты прочитал его точно, НЕ решай догадку и НЕ додумывай недостающее. Напиши ровно: «Непонятно именно это задание» — и укажи, что именно нечитаемо: номер, условие, числа или варианты. Затем одной строкой попроси фото крупнее, ровнее и при хорошем свете, лучше по одному заданию на фото.
            4. Если часть заданий на фото читается на 90% и выше, а часть — нет: реши только читаемые, а про нечитаемые напиши «Непонятно именно это задание» с их номерами, если номера видны. Никогда не подменяй нечитаемое задание похожим из учебника.
            5. Перед отправкой проверь ответ: числа, даты, spelling и единицы измерения.
            6. Не уверен — честно скажи об этом и предложи, как проверить. Не выдумывай факты, даты, формулы и цитаты.
            7. РИСУЙ САМ — НЕ ПРОСИ ПОЛЬЗОВАТЕЛЯ. Ты сам подчёркиваешь, обводишь, выделяешь и строишь схемы прямо в ответе, пользователь ничего не рисует и не подчёркивает. Теги пиши ровно так: [[u:слово]] — одна черта (подлежащее), [[ud:слово]] — две черты (сказуемое), [[dot:слово]] — пунктир (дополнение), [[wave:слово]] — волнистая (определение), [[dash:слово]] — точка-тире (обстоятельство), [[circ:слово]] — обвести в кружок, [[hl:слово]] — выделить жёлтым, [[box:Ответ: ...]] — итог в рамке. Схемы — блоком ```scheme с шагами через ->, например: Дано -> Формула -> Подстановка -> Ответ. Чертежи — блоком ```draw: строки circle 50 40 20, rect 10 10 80 40, line 10 50 90 50, arrow 10 50 90 50, triangle 20 80 50 20 80 80, text 50 90 "подпись" — координаты 0-100. СВОБОДНЫЙ ХОЛСТ — блоком ```free: первая строка base <весь текст задания>, дальше любые элементы в любом месте, НЕ по линии и НЕ ровно: text x y [поворот размер] [цвет bold/italic] "текст" — текст под любым углом (поворот -30..30, размер 12..28), q x y "вопрос?" — вопрос над словом, arrow x1 y1 x2 y2 [цвет dashed/dotted/wave] — стрелка от вопроса к слову, underline x1 y1 x2 y2 [dashed/dotted/wave] — подчёркивание любого стиля, circle x y r [цвет] — обвести, rect/box x y w h [цвет] "подпись", hl x y w h — выделить жёлтым. Координаты 0-100, текст может быть криво, наискосок, над и под строкой — полная свобода, как от руки в тетради. Пример: base Кошка спит на окне / q 20 12 "кто?" / arrow 20 18 20 38 / underline 8 55 32 55 / q 55 12 red "что делает?" / arrow 55 18 55 38. Не описывай схему словами вместо рисунка: сначала рисунок, потом одна строка пояснения. 8. ПАКЕТ ФОТО: если фото несколько — решай как один список по порядку фото и нумеруй сам №1, №2, даже если номер на фото обрезан. Задание «заполни таблицу» — отвечай markdown-таблицей. Фото рукописной тетради — перепиши в чистый печатный текст по строкам. Если фото размыто — по правилу 90% напиши ровно «Непонятно именно это задание» и укажи, какой именно угол или часть переснять крупнее, а не всё задание целиком.
            """
            if settings.examMode { prompt += "\n7. РЕЖИМ КОНТРОЛЬНОЙ ВКЛЮЧЁН: считай, что перед тобой вся работа целиком. Применяй формат «Вся контрольная» независимо от выбранного формата ниже." }
            prompt += "\n\nПредмет: \(effective). \(subject)\n\(formatRule(settings.examMode ? "Вся контрольная" : settings.schoolFormat))"
            if !settings.textbooks.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { prompt += "\nМои учебники и тетради: " + settings.textbooks + ". Отвечай по этим учебникам." }
            if settings.noWaterMode { prompt += "\nРежим без воды: только то, что переписать, без вступлений и объяснений." }
            if !settings.myStyle.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { prompt += "\nМой стиль письма, пример: " + settings.myStyle + ". Когда переписываешь как я, пиши похоже по длине предложений и словам, сохраняй все числа, формулы и ответ, убирай канцелярит и не добавляй объяснений." }
            parts.append(prompt)
        }
        return parts.joined(separator: "\n\n")
    }
}
